    lines: [{ sku: 'DEV-HOUR', qty: 8, discountPercent: 12.5 }],
  });

  assert.ok(result.ok);
  const text = renderInvoiceText(result.value);

  assert.ok(text.includes('12.5% off'));
  // 8 * 9500 = 76000, 12.5% = 9500
  assert.ok(text.includes('-€95.00'));
  // 76000 - 9500 = 66500
  assert.ok(text.includes('€665.00'));
});

test('renderInvoiceText: with automatic tier discount', () => {
  // C-001 is gold tier (5% automatic)
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 8 }],
  });

  assert.ok(result.ok);
  const text = renderInvoiceText(result.value);

  assert.ok(text.includes('5% off'));
  assert.ok(text.includes('Northwind Studio'));
  // 8 * 9500 = 76000, 5% = 3800
  assert.ok(text.includes('-€38.00'));
  assert.ok(text.includes('€722.00'));
});

test('renderInvoiceText: silver tier customer', () => {
  // C-003 is silver tier (2.5% automatic)
  const result = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 8 }],
  });

  assert.ok(result.ok);
  const text = renderInvoiceText(result.value);

  assert.ok(text.includes('2.5% off'));
  assert.ok(text.includes('Kite & Co'));
  // 8 * 9500 = 76000, 2.5% = 1900
  assert.ok(text.includes('-€19.00'));
  assert.ok(text.includes('€741.00'));
});

test('renderInvoiceText: standard tier has no discount', () => {
  // C-002 is standard tier (0% - no discount)
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 8 }],
  });

  assert.ok(result.ok);
  const text = renderInvoiceText(result.value);

  assert.ok(text.includes('Blue Fern Bakery'));
  assert.ok(!text.includes('off'));
  assert.ok(!text.includes('Subtotal:'));
  assert.ok(!text.includes('Discount:'));
  // No discount, so total should be 8 * 9500 = 76000 = €760.00
  assert.ok(text.includes('Total: €760.00'));
});

